import * as React from 'react'
import { Bell, CheckCheck } from 'lucide-react'

import { cx } from '~/lib/cx'
import { Button } from './button'
import { Empty } from './empty'
import styles from './notification-center.module.scss'

export type Notification = {
  id: string
  title: React.ReactNode
  description?: React.ReactNode
  time?: string
  read?: boolean
  icon?: React.ReactNode
  onSelect?: () => void
}

export function NotificationCenter({
  notifications,
  onMarkAllRead,
  label = 'Notifications',
  className,
}: {
  notifications: Notification[]
  onMarkAllRead?: () => void
  label?: string
  className?: string
}) {
  const unread = notifications.filter((item) => !item.read).length

  return (
    <section aria-label={label} className={cx(styles.root, className)}>
      <header className={styles.header}>
        <div className={styles.heading}>
          <Bell className={styles.bell} aria-hidden />
          <h2 className={styles.title}>{label}</h2>
          {unread ? <span className={styles.count}>{unread}</span> : null}
        </div>
        {unread && onMarkAllRead ? (
          <Button
            variant="ghost"
            size="sm"
            onClick={onMarkAllRead}
            className={styles.markAll}
          >
            <CheckCheck aria-hidden />
            Mark all read
          </Button>
        ) : null}
      </header>

      {notifications.length === 0 ? (
        <Empty
          title="All caught up"
          description="New notifications will appear here."
          className={styles.empty}
        />
      ) : (
        <ul className={styles.list} aria-live="polite">
          {notifications.map((item) => (
            <li key={item.id} className={styles.listItem}>
              <button
                type="button"
                onClick={item.onSelect}
                className={cx(styles.item, !item.read && styles.itemUnread)}
              >
                <span className={styles.avatar}>
                  {item.icon ?? <Bell aria-hidden />}
                </span>
                <span className={styles.body}>
                  <span className={styles.titleRow}>
                    <span className={styles.itemTitle}>{item.title}</span>
                    {!item.read ? (
                      <>
                        <span aria-hidden className={styles.dot} />
                        <span className={styles.srOnly}>Unread</span>
                      </>
                    ) : null}
                  </span>
                  {item.description ? (
                    <span className={styles.description}>{item.description}</span>
                  ) : null}
                  {item.time ? (
                    <span className={styles.time}>{item.time}</span>
                  ) : null}
                </span>
              </button>
            </li>
          ))}
        </ul>
      )}
    </section>
  )
}

@use 'styles' as vz;

.root {
  width: 100%;
  max-width: 24rem;
  overflow: hidden;
  border: 1px solid vz.color('border');
  border-radius: vz.radius('xl');
  background: vz.color('card');
  color: vz.color('card-foreground');
  box-shadow: vz.elevation(2);
}

.header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: vz.space(2);
  padding: vz.space(3) vz.space(4);
  border-bottom: 1px solid vz.color('border');
}

.heading {
  display: flex;
  align-items: center;
  gap: vz.space(2);
  min-width: 0;
}

.bell {
  flex: none;
  color: vz.color('muted-foreground');

  @include vz.icon(4);
}

.title {
  margin: 0;
  font-size: vz.font-size('sm');
  font-weight: 600;
  line-height: 1.35;
}

.count {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: vz.space(5);
  padding: 1px vz.space(1.5);
  border-radius: vz.radius('full');
  background: vz.color('primary');
  color: vz.color('primary-foreground');
  font-size: 10px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  line-height: 1.3;
}

.root .mark-all {
  flex: none;
  gap: vz.space(1);
  height: vz.space(7);
  padding-inline: vz.space(2);
  font-size: vz.font-size('xs');

  svg {
    @include vz.icon(3.5);
  }
}

.root .empty {
  padding: vz.space(8) vz.space(4);
  border: 0;
  border-radius: 0;
  background: transparent;
}

.list {
  max-height: 20rem;
  margin: 0;
  padding: 0;
  overflow: auto;
  list-style: none;

  @include vz.scrollbar(10px);
}

.list-item + .list-item {
  border-top: 1px solid vz.color('border');
}

.item {
  display: flex;
  align-items: flex-start;
  gap: vz.space(3);
  width: 100%;
  padding: vz.space(3) vz.space(4);
  border: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition: background-color vz.duration('fast') vz.ease('out');

  @include vz.hover {
    background: vz.color('accent', 0.6);
  }

  &:focus-visible {
    outline: 2px solid vz.color('ring', 0.6);
    outline-offset: -2px;
  }

  @include vz.motion-reduce {
    transition: none;
  }
}

.item-unread {
  background: vz.color('accent', 0.3);
}

.avatar {
  display: inline-flex;
  flex: none;
  align-items: center;
  justify-content: center;
  width: vz.space(7);
  height: vz.space(7);
  margin-top: 2px;
  border-radius: vz.radius('full');
  background: vz.color('muted');
  color: vz.color('muted-foreground');

  svg {
    @include vz.icon(3.5);
  }
}

.body {
  flex: 1;
  min-width: 0;
}

.title-row {
  display: flex;
  align-items: center;
  gap: vz.space(2);
}

.item-title {
  flex: 1;
  min-width: 0;
  font-size: vz.font-size('sm');
  font-weight: 500;

  @include vz.truncate;
}

.dot {
  flex: none;
  width: 6px;
  height: 6px;
  border-radius: vz.radius('full');
  background: vz.color('primary');
}

.description {
  margin-top: 2px;
  color: vz.color('muted-foreground');
  font-size: vz.font-size('xs');

  @include vz.line-clamp(2);
}

.time {
  display: block;
  margin-top: vz.space(1);
  color: vz.color('muted-foreground');
  font-size: 11px;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}
